let t_score = 'ND';
let t_protestos = 'ND';
let t_execucoes = 'ND';
let t_spc = 'ND';
let gate_disparado = null;
let obs_score = null;
let obs_spc_historico = null; // registra ocorrência SPC fora da janela de 1 ano (não pontua, só auditoria)

try {
  const resp = $json;
  const report = Array.isArray(resp) ? resp[0] : resp;
  const rel = report?.reports?.[0] ?? null;

  if (rel) {
    const scoreBlock = report?.optionalFeatures?.score;
    if (scoreBlock && typeof scoreBlock.score === 'number') {
      t_score = scoreBlock.score;
    } else if (scoreBlock?.message) {
      obs_score = scoreBlock.message;
    }

    const protestosCount = rel?.negativeData?.notary?.summary?.count;
    if (typeof protestosCount === 'number') t_protestos = protestosCount;

    const execucoesCount = rel?.facts?.judgementFilings?.summary?.count;
    if (typeof execucoesCount === 'number') t_execucoes = execucoesCount;

    // ---- SPC: só conta como "Já teve ocorrência" se houver item com data
    // dentro do último ano. Ocorrências mais antigas (mesmo 10 anos atrás)
    // não pontuam, mas ficam registradas em obs_spc_historico.
    const spcAnn = report?.optionalFeatures?.spcAnnotations;
    const spcList = Array.isArray(spcAnn?.spcAnnotationsResponseList) ? spcAnn.spcAnnotationsResponseList : null;
    const spcCountTotal = spcAnn?.summary?.count;

    const UM_ANO_MS = 365 * 24 * 60 * 60 * 1000;
    const agora = Date.now();

    if (spcList) {
      let temNoUltimoAno = false;
      let temAntigo = false;

      for (const item of spcList) {
        const dataRef = item?.occurrenceDate ?? item?.inclusionDate;
        if (!dataRef) continue;
        const dt = new Date(dataRef).getTime();
        if (!Number.isFinite(dt)) continue;
        if (agora - dt <= UM_ANO_MS) temNoUltimoAno = true;
        else temAntigo = true;
      }

      t_spc = temNoUltimoAno ? 'Já teve ocorrência no SPC' : 'Sem ocorrência no SPC';
      if (temAntigo) {
        obs_spc_historico = 'Possui ocorrência(s) de SPC registradas há mais de 1 ano (fora da janela considerada para pontuação)';
      }
    } else if (typeof spcCountTotal === 'number') {
      // Fallback: se a Serasa não trouxer a lista detalhada, usa o count agregado
      // (sem filtro de data -- comportamento antigo, só como rede de segurança).
      t_spc = spcCountTotal > 0 ? 'Já teve ocorrência no SPC' : 'Sem ocorrência no SPC';
    }

    const bankruptsCount = rel?.facts?.bankrupts?.summary?.count;
    const emRJDireto = $('When Executed by Another Workflow').item.json.em_recuperacao_judicial === true;

    if (emRJDireto) {
      gate_disparado = 'G2: recuperação judicial (cadastro)';
    } else if (typeof bankruptsCount === 'number' && bankruptsCount > 0) {
      gate_disparado = 'G2: recuperação judicial ou falência (Serasa)';
    }
  }
} catch (e) {}

return [{ json: { t_score, t_protestos, t_execucoes, t_spc, gate_disparado, obs_score, obs_spc_historico } }];

